#requires -Version 7
<#
.SYNOPSIS
Read-only HV mechanical lint for the R2 federation packet.
Verifies source hashes against the export manifest and greps error/outcome tokens
across the planning and requirements documents, emitting file:line receipts.
No mutation of any repository, store, or state occurs.
#>
[CmdletBinding()]
param(
    [string]$Repo = '/home/sharpninja/github/McpServer'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$manifestPath = Join-Path $Repo 'docs/plans/exports/Federation-2026-11-10-R2.manifest.json'
$manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json

Write-Output '=== HASH VERIFICATION (current source vs manifest.sources) ==='
foreach ($entry in $manifest.sources) {
    $full = Join-Path $Repo $entry.path
    if (Test-Path -LiteralPath $full) {
        $actual = (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash
        $state = if ($actual -eq $entry.sha256) { 'MATCH' } else { 'MISMATCH' }
        Write-Output ("{0,-8} {1}" -f $state, $entry.path)
        if ($state -eq 'MISMATCH') {
            Write-Output ("         expected {0}" -f $entry.sha256)
            Write-Output ("         actual   {0}" -f $actual)
        }
    }
    else {
        Write-Output ("MISSING  {0}" -f $entry.path)
    }
}

Write-Output ''
Write-Output '=== TOKEN GREP (file:line) across planning + requirements docs ==='
$docDirs = @(
    (Join-Path $Repo 'docs/plans'),
    (Join-Path $Repo 'docs/Project/federation-dolt')
)
$files = foreach ($d in $docDirs) {
    Get-ChildItem -LiteralPath $d -Filter '*.md' -File -Recurse -ErrorAction SilentlyContinue
}
$files = $files | Sort-Object -Property FullName -Unique

$tokens = @(
    'request_id_conflict',
    'audit_id_conflict',
    'already_applied',
    'already_received',
    'waiting_local_work',
    'publication_required',
    'project_required',
    'maintenance_not_ready',
    'unsupported_capability',
    'unsupported_contract',
    'DoltLite',
    'already_applied counts'
)

foreach ($tok in $tokens) {
    Write-Output ("--- token: {0} ---" -f $tok)
    $hits = 0
    foreach ($f in $files) {
        $rel = $f.FullName.Substring($Repo.Length + 1)
        $n = 0
        foreach ($line in [System.IO.File]::ReadLines($f.FullName)) {
            $n++
            if ($line -like ('*' + $tok + '*')) {
                $hits++
                $trimmed = $line.Trim()
                if ($trimmed.Length -gt 155) { $trimmed = $trimmed.Substring(0, 155) + '...' }
                Write-Output ("{0}:{1}: {2}" -f $rel, $n, $trimmed)
            }
        }
    }
    if ($hits -eq 0) { Write-Output '(none)' }
}

Write-Output ''
Write-Output '=== STABLE FAILURE MAPPING membership check ==='
$contracts = Join-Path $Repo 'docs/plans/2026-11-10-federation-current-contracts.md'
$mapLine = Select-String -LiteralPath $contracts -Pattern 'Stable failure mapping' -SimpleMatch |
    Select-Object -First 1
if ($mapLine) {
    Write-Output ("Mapping at {0}:{1}" -f 'current-contracts.md', $mapLine.LineNumber)
    $codesToCheck = @('request_id_conflict', 'audit_id_conflict', 'waiting_local_work', 'already_applied')
    foreach ($c in $codesToCheck) {
        $present = $mapLine.Line -like ('*' + $c + '*')
        $verdict = if ($present) { 'IN-MAPPING' } else { 'ABSENT-FROM-MAPPING' }
        Write-Output ("{0,-20} {1}" -f $verdict, $c)
    }
}
else {
    Write-Output 'Stable failure mapping line not found.'
}

Write-Output ''
Write-Output '=== DONE ==='

