Runs PSScriptAnalyzer at Warning and Error severities on the target script,
per the operator's "analyze before running against data" rule.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)]
    [string]$Target
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

